import Link from "next/link"

import { cn } from "@/lib/utils"

export function Logo({
  className,
  href = "/",
}: {
  className?: string
  href?: string
}) {
  return (
    <Link
      href={href}
      className={cn(
        "inline-flex items-center gap-2 text-2xl font-semibold tracking-tight text-foreground transition-opacity hover:opacity-90",
        className
      )}
    >
      <svg
        viewBox="0 0 24 24"
        aria-hidden="true"
        className="size-7 text-primary"
        fill="none"
      >
        <rect width="24" height="24" rx="7" fill="currentColor" opacity="0.16" />
        <path
          d="M16.5 8.25A5.25 5.25 0 1 0 17.25 12h-4.5"
          stroke="currentColor"
          strokeWidth="2.25"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
      Geneva
    </Link>
  )
}

import Link from "next/link"

import { Logo } from "@/components/geneva/logo"

const footerLinks = [
  { label: "About us", href: "/about" },
  { label: "Contact us", href: "/contact" },
  { label: "Terms of use", href: "/terms" },
]

export function SiteFooter() {
  return (
    <footer className="border-t border-border">
      <div className="mx-auto flex max-w-7xl flex-col items-center gap-8 px-4 py-12 sm:px-6">
        <Logo className="text-3xl" />
        <nav className="flex flex-wrap justify-center gap-x-8 gap-y-3">
          {footerLinks.map((link) => (
            <Link
              key={link.href}
              href={link.href}
              className="text-sm font-medium text-muted-foreground transition-colors hover:text-foreground"
            >
              {link.label}
            </Link>
          ))}
        </nav>
        <div className="flex w-full flex-col items-center justify-between gap-3 border-t border-border pt-8 text-sm text-muted-foreground sm:flex-row">
          <p>Designed with care by Ismail Mesbah</p>
          <p>© 2026 Geneva. All rights reserved.</p>
        </div>
      </div>
    </footer>
  )
}
